<template>
 <div ref="screenRoot" class="screen-editor" :class="{compact}">
 <div v-if="readonly" class="screen-display-tools"><button @click="toggleFullscreen">{{ fullscreen?'退出全屏':'全屏展示' }}</button><span v-if="fullscreenError" role="status">{{ fullscreenError }}</span></div>
 <div v-if="!readonly && !compact" class="viewport-tools" role="toolbar" aria-label="大屏画布工具">
  <button :aria-pressed="panMode" @click="panMode=!panMode">{{ panMode?'切换选择':'平移画布' }}</button>
  <button :aria-pressed="rulers" @click="rulers=!rulers">标尺</button>
  <button :aria-pressed="snapping" @click="snapping=!snapping">参考线吸附</button>
  <button :disabled="disabled || guides.length>=20" @click="addGuide('x')">添加垂直参考线</button>
  <button :disabled="disabled || guides.length>=20" @click="addGuide('y')">添加水平参考线</button>
  <button :disabled="disabled || !guides.length" @click="guides=[]">清除参考线</button>
  <button @click="resetViewport">复位视口</button>
  <span>视口与参考线仅供编辑，不保存</span>
 </div>
 <div v-if="!readonly && compact" class="compact-viewport-tools" role="toolbar" aria-label="大屏画布工具">
  <button title="适应画布" @click="fitViewport"><el-icon><Monitor /></el-icon><span>适应画布</span></button>
  <span class="viewport-divider" />
  <button aria-label="缩小画布" :disabled="(zoom || 100)<=25" @click="changeZoom(-20)"><el-icon><Minus /></el-icon></button>
  <span class="viewport-scale" aria-live="polite">{{ Math.round(scale*100) }}%</span>
  <button aria-label="放大画布" :disabled="(zoom || 100)>=400" @click="changeZoom(20)"><el-icon><Plus /></el-icon></button>
  <span class="viewport-divider" />
  <button :aria-pressed="panMode" aria-label="平移画布" title="平移画布" @click="panMode=!panMode"><el-icon><Rank /></el-icon></button>
  <button :aria-pressed="rulers" aria-label="显示标尺" title="显示标尺" @click="rulers=!rulers"><el-icon><SetUp /></el-icon></button>
  <button :aria-pressed="snapping" aria-label="参考线吸附" title="参考线吸附" @click="snapping=!snapping"><el-icon><Magnet /></el-icon></button>
  <el-dropdown trigger="click" @command="handleViewportCommand"><button aria-label="参考线与视口设置" title="参考线与视口设置"><el-icon><MoreFilled /></el-icon></button><template #dropdown><el-dropdown-menu>
   <el-dropdown-item command="x" :disabled="disabled || guides.length>=20">添加垂直参考线</el-dropdown-item>
   <el-dropdown-item command="y" :disabled="disabled || guides.length>=20">添加水平参考线</el-dropdown-item>
   <el-dropdown-item command="clear" :disabled="disabled || !guides.length">清除参考线</el-dropdown-item>
   <el-dropdown-item command="reset">复位视口</el-dropdown-item>
  </el-dropdown-menu></template></el-dropdown>
 </div>
 <div v-if="!readonly && guides.length" class="guide-list"><label v-for="g in guides" :key="g.id">{{g.axis==='x'?'垂直':'水平'}}<input type="number" :aria-label="'参考线'+g.id+'坐标'" :value="g.position" min="0" :max="g.axis==='x'?scene.width:scene.height" :disabled="disabled" @change="editGuide(g,$event)"/><button :disabled="disabled" :aria-label="'删除参考线'+g.id" @click="guides=guides.filter(v=>v.id!==g.id)">×</button></label></div>
 <p v-if="!readonly && panels.length && panels.every(p=>p.hidden)" class="screen-hidden-note">所有组件均已隐藏，请在“组件与图层”中选择组件后显示。</p>
 <div ref="frame" class="screen-frame" :class="{'editing':!readonly,'pan-mode':!readonly && panMode}" :style="presentationVars(appearance)" @pointerdown.capture="beginPan">
 <div class="screen-region" :style="regionStyle"><div class="screen-sheet" :style="sheetStyle"><article v-for="(panel,i) in panels.filter(p=>!p.hidden)" :key="panel.key" :data-screen-id="panel.key" class="screen-panel" :class="{decoration:panel.componentType==='border' || panel.componentType==='line' || panel.componentType==='container',selected:!readonly && (selectedKey===panel.key || selectedKeys?.includes(panel.key))}" :style="panelStyle(panel,i)" :tabindex="readonly?-1:0" :aria-label="(readonly?'大屏组件 ':'选择大屏组件 ')+panel.key" @pointerdown="begin(panel,$event,false)" @keydown.enter="!readonly && !panMode && emit('select',panel.key)"><slot :panel="panel"/><button v-if="!readonly && !disabled && !panel.locked && !panel.groupKey && !(panel.componentType==='container' && panels.some(p=>p.parentKey===panel.key)) && !panMode" class="resize-handle" :aria-label="'缩放大屏组件 '+panel.key" @pointerdown.stop="begin(panel,$event,true)"/></article></div></div>
 <template v-if="!readonly">
  <strong v-for="p in panels.filter(p=>p.componentType==='container' && !p.hidden && selectedKey===p.key)" :key="'move-'+p.key" class="container-mover panel-handle" role="button" :aria-label="'移动容器 '+p.key" :style="{left:origin.x+p.x*scale+'px',top:origin.y+p.y*scale-20+'px'}" @pointerdown.stop="begin(p,$event,false)">移动容器</strong>
  <div v-if="rulers" class="ruler horizontal" aria-hidden="true"><span v-for="n in rulerTicks(scene.width,scale)" :key="n" :style="{left:origin.x+n*scale+'px'}">{{n}}</span></div>
  <div v-if="rulers" class="ruler vertical" aria-hidden="true"><span v-for="n in rulerTicks(scene.height,scale)" :key="n" :style="{top:origin.y+n*scale+'px'}">{{n}}</span></div>
  <button v-for="g in guides" :key="g.id" class="guide" :class="g.axis==='x'?'guide-x':'guide-y'" :style="g.axis==='x'?{left:origin.x+g.position*scale+'px'}:{top:origin.y+g.position*scale+'px'}" :disabled="disabled || panMode" :aria-label="(g.axis==='x'?'垂直':'水平')+'参考线'+g.id+'，'+g.position+'像素，拖动调整'" @pointerdown.stop="beginGuide(g,$event)"/>
 </template>
 </div></div>
</template>
<script setup lang="ts" generic="T extends PanelLayout">
import {ref,computed,watch,onMounted,onBeforeUnmount,onDeactivated} from 'vue'
import { Monitor, Minus, Plus, Rank, SetUp, Magnet, MoreFilled } from '@element-plus/icons-vue'
import type {CSSProperties} from 'vue'
import type {PanelLayout,DashboardAppearance,ScreenScene} from '@/api/bi/dashboard'
import {rulerTicks,guidePosition,snapAxis} from '@/utils/biScreenViewport'
import {presentationVars} from '@/utils/biPresentation'
const props=defineProps<{panels:T[];scene:ScreenScene;zoom?:number;compact?:boolean;readonly?:boolean;disabled?:boolean;appearance?:DashboardAppearance;selectedKey?:string;selectedKeys?:string[]}>()
const emit=defineEmits<{(event:'zoom',value:number):void;(event:'change',items:PanelLayout[]):void;(event:'select',key:string,additive?:boolean):void}>()
const screenRoot=ref<HTMLElement>(),fullscreen=ref(false),fullscreenError=ref('')
async function toggleFullscreen(){fullscreenError.value='';try{if(document.fullscreenElement===screenRoot.value)await document.exitFullscreen();else if(screenRoot.value?.requestFullscreen)await screenRoot.value.requestFullscreen();else fullscreenError.value='当前浏览器不支持全屏展示'}catch{fullscreenError.value='当前浏览器未允许全屏，请在支持全屏的浏览器中打开'}}
function syncFullscreen(){fullscreen.value=document.fullscreenElement===screenRoot.value}
function leaveFullscreen(){if(document.fullscreenElement===screenRoot.value)void document.exitFullscreen().catch(()=>{})}
function fullscreenKey(event:KeyboardEvent){if(event.key==='Escape' && document.fullscreenElement===screenRoot.value){event.stopPropagation();leaveFullscreen()}}
const frame=ref<HTMLElement>(),size=ref({width:800,height:500}),draft=ref<PanelLayout>(),groupDraft=ref<PanelLayout[]>([])
const scale=computed(()=>{const width=Math.max(1,size.value.width-(!props.readonly && rulers.value?22:0)),height=Math.max(1,size.value.height-(!props.readonly && rulers.value?20:0));const fit=props.compact && !props.readonly?Math.min(width/props.scene.width,height/props.scene.height):props.scene.fit==='none'?1:props.scene.fit==='width'?width/props.scene.width:Math.min(width/props.scene.width,height/props.scene.height);return Math.max(.02,fit*(props.readonly?1:(props.zoom || 100)/100))})
type Guide={id:number;axis:'x'|'y';position:number}
const panMode=ref(false),rulers=ref(true),snapping=ref(true),pan=ref({x:0,y:0}),guides=ref<Guide[]>([])
let guideId=0,viewportDrag:{pointer:number;x:number;y:number;pan:{x:number;y:number}}|undefined,guideDrag:Guide|undefined
const origin=computed(()=>{const left=!props.readonly && rulers.value?22:0,top=!props.readonly && rulers.value?20:0;return {x:left+Math.max(0,(size.value.width-left-props.scene.width*scale.value)/2)+(props.readonly?0:pan.value.x),y:top+Math.max(0,(size.value.height-top-props.scene.height*scale.value)/(props.compact?2.5:2))+(props.readonly?0:pan.value.y)}})
function resetViewport(){cancel();pan.value={x:0,y:0};if(frame.value){frame.value.scrollLeft=0;frame.value.scrollTop=0}}
function changeZoom(delta:number){emit('zoom',Math.max(25,Math.min(400,(props.zoom || 100)+delta)))}
function fitViewport(){emit('zoom',100);resetViewport()}
function handleViewportCommand(command:string){if(command==='x' || command==='y')addGuide(command);if(command==='clear' && !props.disabled)guides.value=[];if(command==='reset')resetViewport()}
function addGuide(axis:'x'|'y'){if(props.disabled || guides.value.length>=20)return;guides.value.push({id:++guideId,axis,position:Math.round((axis==='x'?props.scene.width:props.scene.height)/2)})}
function editGuide(g:Guide,event:Event){const input=event.target as HTMLInputElement,n=Number(input.value),limit=g.axis==='x'?props.scene.width:props.scene.height;if(input.value!=='' && Number.isInteger(n) && n>=0 && n<=limit)g.position=n;input.value=String(g.position)}
function beginPan(event:PointerEvent){if(props.readonly || !panMode.value || event.button!==0)return;event.preventDefault();event.stopPropagation();viewportDrag={pointer:event.pointerId,x:event.clientX,y:event.clientY,pan:{...pan.value}}}
function beginGuide(g:Guide,event:PointerEvent){if(props.disabled || panMode.value || event.button!==0)return;event.preventDefault();guideDrag=g;drag=undefined;guidePointer=event.pointerId}
let guidePointer=0
const sheetStyle=computed<CSSProperties>(()=>({width:props.scene.width+'px',height:props.scene.height+'px',transform:`scale(${scale.value})`}))
const regionStyle=computed<CSSProperties>(()=>({width:props.scene.width*scale.value+'px',height:props.scene.height*scale.value+'px',left:origin.value.x+'px',top:origin.value.y+'px'}))
function panelStyle(panel:T,i:number):CSSProperties{const p=groupDraft.value.find(p=>p.key===panel.key) || (draft.value?.key===panel.key?draft.value:panel);return {left:p.x+'px',top:p.y+'px',width:p.w+'px',height:p.h+'px',zIndex:i+1}}
let observer:ResizeObserver|undefined,drag:{members:PanelLayout[];panel:PanelLayout;x:number;y:number;resize:boolean;pointer:number;scale:number}|undefined
function begin(panel:T,event:PointerEvent,resize:boolean){if(props.readonly || panMode.value || event.button!==0)return;emit('select',panel.key,event.ctrlKey || event.metaKey || event.shiftKey);if(props.disabled || panel.locked || drag || (!resize && (!(event.target as Element).closest('.panel-handle') || (event.target as Element).closest('button,input,select,textarea'))))return;const members=props.panels.filter(p=>panel.componentType==='container'?(p.key===panel.key || p.parentKey===panel.key):panel.groupKey?p.groupKey===panel.groupKey:p.key===panel.key);if(members.some(p=>p.locked) || (resize && (panel.groupKey || (panel.componentType==='container' && members.length>1))))return;event.preventDefault();drag={members:members.map(p=>({...p})),panel:{...panel},x:event.clientX,y:event.clientY,resize,pointer:event.pointerId,scale:scale.value};draft.value={...panel}}
function move(event:PointerEvent){
 if(viewportDrag?.pointer===event.pointerId){event.preventDefault();pan.value={x:viewportDrag.pan.x+event.clientX-viewportDrag.x,y:viewportDrag.pan.y+event.clientY-viewportDrag.y};return}
 if(guideDrag && guidePointer===event.pointerId){const rect=frame.value?.getBoundingClientRect();if(rect){const x=guideDrag.axis==='x';guideDrag.position=guidePosition(x?event.clientX:event.clientY,(x?rect.left+origin.value.x:rect.top+origin.value.y)+1,scale.value,x?props.scene.width:props.scene.height)}return}
if(!drag || drag.pointer!==event.pointerId)return;event.preventDefault();const p=drag.panel,dx=Math.round((event.clientX-drag.x)/drag.scale),dy=Math.round((event.clientY-drag.y)/drag.scale);if(drag.members.length>1){const members=drag.members,left=Math.min(...members.map(p=>p.x)),top=Math.min(...members.map(p=>p.y)),right=Math.max(...members.map(p=>p.x+p.w)),bottom=Math.max(...members.map(p=>p.y+p.h));let x=Math.max(0,Math.min(props.scene.width-(right-left),left+dx)),y=Math.max(0,Math.min(props.scene.height-(bottom-top),top+dy));if(snapping.value){x=snapAxis(x,right-left,props.scene.width,guides.value.filter(g=>g.axis==='x').map(g=>g.position),6/drag.scale);y=snapAxis(y,bottom-top,props.scene.height,guides.value.filter(g=>g.axis==='y').map(g=>g.position),6/drag.scale)}groupDraft.value=members.map(p=>({...p,x:p.x+x-left,y:p.y+y-top}));return}const parent=props.panels.find(v=>v.key===p.parentKey),pad=parent?.content?.container?.padding || 0,minX=parent?parent.x+pad:0,minY=parent?parent.y+pad:0,maxX=parent?parent.x+parent.w-pad:props.scene.width,maxY=parent?parent.y+parent.h-pad:props.scene.height;draft.value=drag.resize?{...p,w:Math.max(20,Math.min(maxX-p.x,p.w+dx)),h:Math.max(20,Math.min(maxY-p.y,p.h+dy))}:{...p,x:Math.max(minX,Math.min(maxX-p.w,p.x+dx)),y:Math.max(minY,Math.min(maxY-p.h,p.y+dy))};if(snapping.value && draft.value){const n=draft.value;const xs=guides.value.filter(g=>g.axis==='x').map(g=>g.position),ys=guides.value.filter(g=>g.axis==='y').map(g=>g.position);if(drag.resize){n.w=snapAxis(n.x,n.w,props.scene.width,xs,6/drag.scale,true);n.h=snapAxis(n.y,n.h,props.scene.height,ys,6/drag.scale,true)}else{n.x=snapAxis(n.x,n.w,props.scene.width,xs,6/drag.scale);n.y=snapAxis(n.y,n.h,props.scene.height,ys,6/drag.scale)}}if(draft.value && parent){const n=draft.value;if(drag.resize){n.x=p.x;n.y=p.y;n.w=Math.min(n.w,maxX-p.x);n.h=Math.min(n.h,maxY-p.y)}else{n.x=Math.max(minX,Math.min(maxX-n.w,n.x));n.y=Math.max(minY,Math.min(maxY-n.h,n.y));n.w=Math.min(n.w,maxX-n.x);n.h=Math.min(n.h,maxY-n.y)}}}
function finish(event:PointerEvent){if(viewportDrag?.pointer===event.pointerId){viewportDrag=undefined;return}if(guideDrag && guidePointer===event.pointerId){guideDrag=undefined;return}if(!drag || drag.pointer!==event.pointerId)return;const changes=groupDraft.value.length?groupDraft.value:(draft.value?[draft.value]:[]);const members=drag.members;drag=undefined;draft.value=undefined;groupDraft.value=[];if(members.length>1){if(!props.disabled && members.every(p=>props.panels.some(v=>v.key===p.key && !v.locked && v.groupKey===p.groupKey && v.parentKey===p.parentKey)))emit('change',changes);return}const next=changes[0];if(next && !props.disabled && !props.panels.find(p=>p.key===next.key)?.locked)emit('change',[next])}
function cancel(){viewportDrag=undefined;guideDrag=undefined;drag=undefined;draft.value=undefined;groupDraft.value=[]}
watch(()=>[props.readonly,props.disabled,props.scene.width,props.scene.height,props.zoom,props.scene.fit,panMode.value,rulers.value,size.value.width,size.value.height],()=>{cancel();guides.value=guides.value.filter(g=>g.position<=(g.axis==='x'?props.scene.width:props.scene.height))})
onMounted(()=>{document.addEventListener('fullscreenchange',syncFullscreen);document.addEventListener('keydown',fullscreenKey);observer=new ResizeObserver(()=>{if(frame.value)size.value={width:frame.value.clientWidth,height:frame.value.clientHeight}});if(frame.value)observer.observe(frame.value);window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',finish);window.addEventListener('pointercancel',cancel);window.addEventListener('blur',cancel)})
onDeactivated(()=>{cancel();leaveFullscreen()})
onBeforeUnmount(()=>{document.removeEventListener('fullscreenchange',syncFullscreen);document.removeEventListener('keydown',fullscreenKey);leaveFullscreen();observer?.disconnect();window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',cancel);window.removeEventListener('blur',cancel);cancel()})
</script>
<style scoped>
.container-mover{position:absolute;z-index:98;background:#3370ff;color:white;font-size:11px;line-height:20px;padding:0 8px;border-radius:3px;cursor:move;touch-action:none}.screen-hidden-note{font-size:12px;color:#7f8b9d}.screen-display-tools{display:flex;align-items:center;gap:10px;justify-content:flex-end;margin-bottom:8px;font-size:12px;color:#8b96a7}.screen-display-tools button{background:white;border:1px solid #ccd5e1;border-radius:4px;padding:6px 12px;color:#34455f;cursor:pointer}.screen-editor:fullscreen{box-sizing:border-box;padding:8px;background:#111827;overflow:auto}.screen-editor:fullscreen .screen-frame{height:calc(100vh - 50px);min-height:0;border:0;border-radius:0}

.viewport-tools,.guide-list{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-bottom:8px;font-size:11px;color:#65738a}.viewport-tools button,.guide-list button{border:1px solid #ccd5e1;border-radius:4px;background:white;padding:5px 8px;color:#34455f;cursor:pointer}.viewport-tools button[aria-pressed=true]{color:#2460d9;border-color:#3370ff;background:#eef4ff}.viewport-tools button:disabled{opacity:.45;cursor:default}.guide-list label{display:flex;align-items:center;gap:4px}.guide-list input{width:70px;border:1px solid #ccd5e1;padding:4px}.screen-frame:not(.editing){background:var(--bi-background)}.screen-frame.editing{overflow:hidden;touch-action:none}.pan-mode,.pan-mode *{cursor:grab!important}.ruler{position:absolute;z-index:100;background:#f3f6fae8;color:#56677c;font-size:10px;pointer-events:none;overflow:hidden}.horizontal{top:0;left:0;right:0;height:20px;border-bottom:1px solid #acb9cb}.vertical{left:0;top:20px;bottom:0;width:22px;border-right:1px solid #acb9cb}.ruler span{position:absolute;white-space:nowrap}.horizontal span{height:20px;border-left:1px solid #899bb3;padding-left:3px}.vertical span{width:22px;border-top:1px solid #899bb3;writing-mode:vertical-rl;padding-top:3px;transform:translateY(-20px)}.guide{position:absolute;z-index:99;background:transparent;border:0;padding:0;touch-action:none}.guide-x{top:20px;bottom:0;width:9px;transform:translateX(-4px);cursor:ew-resize;background:linear-gradient(to right,transparent 4px,#e949a3 4px,#e949a3 5px,transparent 5px)}.guide-y{left:22px;right:0;height:9px;transform:translateY(-4px);cursor:ns-resize;background:linear-gradient(to bottom,transparent 4px,#e949a3 4px,#e949a3 5px,transparent 5px)}
.screen-frame{position:relative;height:70vh;min-height:360px;overflow:auto;background:#dce3ed;border:1px solid var(--bi-border);border-radius:8px}.screen-region{position:absolute;overflow:hidden}.screen-sheet{position:absolute;transform-origin:top left;background:var(--bi-background);box-shadow:0 5px 20px #172c4d22;color:var(--bi-text)}.screen-panel{display:flex;flex-direction:column;position:absolute;background:var(--bi-card);border:1px solid var(--bi-border);border-radius:var(--bi-radius);overflow:auto;box-sizing:border-box}.screen-panel.decoration{pointer-events:none;background:transparent;border:0;border-radius:0;box-shadow:none}.screen-panel.decoration :deep(.decoration-header),.screen-panel.decoration .resize-handle{pointer-events:auto}.screen-panel.selected{outline:3px solid #3370ff;outline-offset:-3px}.resize-handle{position:absolute;right:0;bottom:0;width:22px;height:22px;cursor:nwse-resize;background:linear-gradient(135deg,transparent 55%,#3370ff 55%);border:0;touch-action:none}.screen-panel :deep(.panel-handle){touch-action:none}.screen-panel :deep(.el-table){--el-table-bg-color:var(--bi-card);--el-table-tr-bg-color:var(--bi-card);--el-table-text-color:var(--bi-text);--el-table-header-text-color:var(--bi-text)}.screen-panel :deep(.panel-body){flex:1;min-height:0;overflow:auto}.screen-panel :deep(.panel-header){flex-shrink:0}.screen-panel :deep(.static-image){min-height:0;height:100%}.screen-panel :deep(.static-image img){height:100%;max-height:100%;width:auto}.screen-panel :deep(.kpi-content){min-height:0;height:100%;box-sizing:border-box;padding:8px;gap:8px}
.screen-editor.compact{height:100%;min-height:0;position:relative}.compact .screen-frame{height:100%;min-height:0;border:0;border-radius:0;background:transparent}.compact .screen-frame.editing{background:transparent}.compact .ruler{background:#f6f8fce8;color:#8b98af}.compact .horizontal{border-bottom:1px solid #e1e7f2}.compact .vertical{border-right:1px solid #e1e7f2}.compact .ruler span{border-color:#d3deed}.compact .guide-list{position:absolute;top:24px;left:30px;right:0;z-index:110;background:#fff;padding:6px;border:1px solid #e6ebf3;border-radius:6px}.compact .screen-panel .resize-handle{opacity:0}.compact .screen-panel:hover .resize-handle,.compact .screen-panel.selected .resize-handle,.compact .screen-panel:focus-within .resize-handle{opacity:1}.compact .screen-panel :deep(.panel-header .el-button){display:none}.compact .screen-panel :deep(.decoration-header){opacity:0}.compact .screen-panel.selected :deep(.decoration-header),.compact .screen-panel:hover :deep(.decoration-header){opacity:1}
.compact-viewport-tools{position:absolute;z-index:150;bottom:-44px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:3px;background:#fff;padding:7px 10px;border:1px solid #e6ebf3;border-radius:10px;box-shadow:0 3px 16px #18345b0a;white-space:nowrap;color:#526079}.compact-viewport-tools button{height:31px;min-width:29px;border:0;padding:0 7px;display:flex;align-items:center;justify-content:center;gap:7px;border-radius:5px;background:transparent;color:inherit;font:inherit;font-size:12px;cursor:pointer}.compact-viewport-tools .el-icon{font-size:16px}.compact-viewport-tools button:hover,.compact-viewport-tools button[aria-pressed=true]{background:#edf2ff;color:#3563e9}.compact-viewport-tools button:disabled{opacity:.4;cursor:not-allowed}.compact-viewport-tools button:focus-visible{outline:2px solid #3563e9;outline-offset:-2px}.viewport-divider{height:18px;border-left:1px solid #e6ebf3;margin:0 3px}.viewport-scale{font-size:12px;min-width:40px;text-align:center;color:#344563;font-variant-numeric:tabular-nums}
@media(max-width:700px){.compact-viewport-tools{bottom:-45px;max-width:100%;gap:0;padding:5px}.compact-viewport-tools button{min-width:24px;padding:0 4px}.compact-viewport-tools button>span{display:none}.viewport-divider{margin:0 2px}.viewport-scale{min-width:33px}.compact .ruler{font-size:8px}}
</style>
